package com.alibaba.fastjson.util;

import org.junit.Test;

import static org.junit.Assert.*;

public class IdentityHashMapTest {

    @Test
    public void testFindClassWithCollision() {
        // Create a small map to force hash collisions
        IdentityHashMap<Class, Object> map = new IdentityHashMap<Class, Object>(2);

        // Collect all Class objects from common packages to find two that collide
        Class[] candidates = new Class[]{
            String.class, Integer.class, Long.class, Double.class, Float.class,
            Boolean.class, Byte.class, Short.class, Character.class,
            Object.class, Class.class, String[].class, int[].class, long[].class,
            java.util.ArrayList.class, java.util.LinkedList.class,
            java.util.HashMap.class, java.util.HashSet.class,
            java.util.TreeMap.class, java.util.TreeSet.class,
            java.util.Hashtable.class, java.util.Vector.class,
            java.util.Properties.class, java.util.Dictionary.class,
            java.lang.System.class, java.lang.Throwable.class,
            java.lang.Exception.class, java.lang.RuntimeException.class,
            java.lang.Number.class, java.lang.Iterable.class,
            java.lang.Cloneable.class, java.io.Serializable.class,
            java.math.BigDecimal.class, java.math.BigInteger.class,
            java.util.Date.class, java.util.Calendar.class,
            java.util.GregorianCalendar.class, java.util.TimeZone.class
        };

        // Put all candidates into the map
        for (Class<?> c : candidates) {
            map.put(c, null);
        }

        // Now try findClass for each candidate
        // If findClass has the bug, it will miss any class that is NOT
        // the head of its bucket chain (because it checks bucket.key instead of entry.key)
        for (Class<?> c : candidates) {
            Class<?> found = map.findClass(c.getName());
            assertNotNull("findClass should find " + c.getName() + " but returned null", found);
            assertEquals(c, found);
        }
    }

    @Test
    public void testFindClassReturnsCorrectClassForCollision() {
        // Smaller targeted test: find two specific classes that hash to the same bucket
        IdentityHashMap<Class, Object> map = new IdentityHashMap<Class, Object>(2);

        int bucket1 = System.identityHashCode(String.class) & 1;
        int bucket2 = System.identityHashCode(Integer.class) & 1;

        if (bucket1 != bucket2) {
            // String and Integer don't collide; try others
            // We need to find a pair that does collide
            boolean found = false;
            Class[] classes = new Class[]{
                String.class, Integer.class, Long.class, Double.class, Float.class,
                Boolean.class, Byte.class, Short.class, Character.class, Object.class
            };
            for (int i = 0; i < classes.length && !found; i++) {
                for (int j = i + 1; j < classes.length && !found; j++) {
                    if ((System.identityHashCode(classes[i]) & 1) == (System.identityHashCode(classes[j]) & 1)) {
                        Class<?> head = classes[i];
                        Class<?> tail = classes[j];
                        // Put tail first so it's second in the chain (head becomes head of chain)
                        map.put(tail, null);
                        map.put(head, null);
                        // Now chain is: head -> tail
                        // findClass for tail should find it, but with the bug it only checks head
                        Class<?> foundClass = map.findClass(tail.getName());
                        assertNotNull("findClass should find " + tail.getName() + " in chain tail but returned null", foundClass);
                        assertEquals(tail, foundClass);
                        found = true;
                    }
                }
            }
        } else {
            // String and Integer collide - great!
            // Put Integer first, then String (String becomes head)
            map.put(Integer.class, null);
            map.put(String.class, null);
            // Chain: String -> Integer
            // findClass for Integer should work, but bug checks String only
            Class<?> found = map.findClass(Integer.class.getName());
            assertNotNull("findClass should find Integer in chain but returned null", found);
            assertEquals(Integer.class, found);
        }
    }
}

