package com.alibaba.json.bvt.parser;

import java.util.HashMap;
import java.util.Map;

import org.junit.Assert;
import junit.framework.TestCase;

import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONException;
import com.alibaba.fastjson.parser.DefaultJSONParser;
import com.alibaba.fastjson.parser.ParserConfig;

public class DefaultJSONParserTest_error extends TestCase {

    public void test_error_1() {
        String text = "{\"obj\":{}]}";
        char[] chars = text.toCharArray();
        DefaultJSONParser parser = new DefaultJSONParser(chars, chars.length, ParserConfig.getGlobalInstance(), 0);

        JSONException error = null;
        try {
            parser.parseObject();
        } catch (JSONException ex) {
            error = ex;
        }
        Assert.assertNotNull(error);
    }

    public void test_error_2() {
        String text = "{\"obj\":[]]}";
        char[] chars = text.toCharArray();
        DefaultJSONParser parser = new DefaultJSONParser(chars, chars.length, ParserConfig.getGlobalInstance(), 0);

        JSONException error = null;
        try {
            parser.parseObject();
        } catch (JSONException ex) {
            error = ex;
        }
        Assert.assertNotNull(error);
    }

    public void test_error_3() {
        String text = "{\"obj\":true]}";
        char[] chars = text.toCharArray();
        DefaultJSONParser parser = new DefaultJSONParser(chars, chars.length, ParserConfig.getGlobalInstance(), 0);

        JSONException error = null;
        try {
            parser.parseObject();
        } catch (JSONException ex) {
            error = ex;
        }
        Assert.assertNotNull(error);
    }

    /**
     * Test that flat JSON with more than 512 object/array keys at the same level
     * should parse successfully without throwing "object key level > 512".
     * The objectKeyLevel counter is incremented for each object key but never
     * decremented, causing it to incorrectly reject flat objects with >512 keys.
     */
    public void test_objectKeyLevel_notIncrementedFlatKeys() {
        // Build a JSON string with >512 object keys at the SAME nesting level.
        // Each key is an empty object {} - this exercises the ch == '{' branch
        // in DefaultJSONParser.parseObject(Map, Object) at line 286-292.
        int count = 600; // well above 512 to trigger the bug
        StringBuilder sb = new StringBuilder();
        sb.append("{");
        for (int i = 0; i < count; i++) {
            if (i > 0) sb.append(",");
            sb.append("{\"k\":\"").append(i).append("\"}");
            sb.append(":\"v").append(i).append("\"");
        }
        sb.append("}");

        // This should parse successfully - 600 flat keys should not cause "object key level > 512"
        Map<String, Object> result = JSON.parseObject(sb.toString(), HashMap.class);
        Assert.assertNotNull(result);
        Assert.assertEquals(count, result.size());
    }
}

