package com.alibaba.json.bvt;

import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.annotation.JSONField;
import com.alibaba.fastjson.parser.deserializer.DefaultFieldDeserializer;
import java.util.zip.GZIPInputStream;
import junit.framework.TestCase;
import org.junit.Assert;

/**
 * Test that GZIPInputStream is properly closed after decompressing gzip-formatted byte[] fields.
 * This tests the resource leak in DefaultFieldDeserializer.parseField where GZIPInputStream
 * was created but never closed.
 */
public class ByteArrayFieldGzipLeakTest extends TestCase {

    public void test_gzipStreamClosed() throws Exception {
        // Prepare data
        Model model = new Model();
        StringBuffer buf = new StringBuffer();
        for (int i = 0; i < 100; ++i) {
            buf.append("Hello World! ");
        }
        model.value = buf.toString().getBytes();

        // Serialize with gzip format
        String json = JSON.toJSONString(model);

        // Parse back - this exercises the gzip decompression path
        DefaultFieldDeserializer.clearLastGzipIn();
        Model model1 = JSON.parseObject(json, Model.class);

        // Verify data round-trip works correctly
        Assert.assertArrayEquals(model.value, model1.value);

        // Get the GZIPInputStream that was created during parsing
        GZIPInputStream gzipIn = DefaultFieldDeserializer.getLastGzipIn();
        assertNotNull("GZIPInputStream should have been created during parsing", gzipIn);

        // The stream SHOULD be closed after use. If it's still open, the bug exists.
        // We check by attempting to read from it - a closed stream throws IOException.
        boolean streamIsClosed = isStreamClosed(gzipIn);
        assertTrue("GZIPInputStream should be closed after decompression but was not (resource leak)", streamIsClosed);
    }

    /**
     * Check if a GZIPInputStream is closed by trying to read from it.
     * Returns true if the stream is closed, false if still open.
     */
    private boolean isStreamClosed(GZIPInputStream gzipIn) {
        try {
            gzipIn.read(new byte[1]);
            return false; // still open
        } catch (Exception e) {
            return true; // closed or error (which is fine for this test)
        }
    }

    public static class Model {
        @JSONField(format = "gzip")
        public byte[] value;
    }
}

