package com.alibaba.json.bvt;

import org.junit.Assert;
import junit.framework.TestCase;

import com.alibaba.fastjson.parser.SymbolTable;

public class SymbolTableTest extends TestCase {

    protected String[] symbols      = new String[] { "EffectedRowCount", "DataSource", "BatchSizeMax", "BatchSizeTotal", "ConcurrentMax", "ErrorCount",
            "ExecuteCount", "FetchRowCount", "File", "ID", "LastError", "LastTime", "MaxTimespan", "MaxTimespanOccurTime", "Name", "RunningCount", "SQL",
            "TotalTime"            };
    char[][]           symbols_char = new char[symbols.length][];
    final int          COUNT        = 1000 * 1000;

    protected void setUp() throws Exception {
        for (int i = 0; i < symbols.length; ++i) {
            symbols_char[i] = symbols[i].toCharArray();
        }
    }

    public void test_symbol() throws Exception {

        char[][] symbols_char = new char[symbols.length][];
        for (int i = 0; i < symbols.length; ++i) {
            symbols_char[i] = symbols[i].toCharArray();
        }



        SymbolTable table = new SymbolTable(512);
        for (int i = 0; i < symbols.length; ++i) {
            String symbol = symbols[i];
            char[] charArray = symbol.toCharArray();
            table.addSymbol(charArray, 0, charArray.length);
            //System.out.println((table.hash(symbol) & table.getIndexMask()) + "\t\t:" + symbol + "\t\t" + table.hash(symbol));
        }

        String symbol = "name";
        table.addSymbol(symbol.toCharArray(), 0, symbol.length());
        table.addSymbol(symbol.toCharArray(), 0, symbol.length());

        Assert.assertTrue(symbol == table.addSymbol("name".toCharArray(), 0, 4));
        Assert.assertTrue(symbol == table.addSymbol(" name".toCharArray(), 1, 4));
        Assert.assertTrue(symbol == table.addSymbol(" name ".toCharArray(), 1, 4));
        Assert.assertTrue(symbol != table.addSymbol(" namf ".toCharArray(), 1, 4));
    }

    /**
     * When two different strings hash to the same bucket (collision), repeated
     * calls for the colliding string must return the SAME reference (interning
     * contract).  Without chaining, a colliding entry is never stored, so each
     * call creates a new String — identity equality breaks.
     */
    public void test_collision_identity() throws Exception {
        // table size 4 → indexMask = 3
        // 'A' hash = 65 → bucket 1,  'E' hash = 69 → bucket 1 (collision)
        SymbolTable table = new SymbolTable(4);
        // occupy bucket 1 with "A"
        table.addSymbol("A".toCharArray(), 0, 1);

        char[] e = "E".toCharArray();
        int eHash = SymbolTable.hash(e, 0, 1);
        // sanity: both land in bucket 1
        Assert.assertEquals(1, eHash & 3);

        // repeated lookups of the same string must return the SAME reference
        String first  = table.addSymbol(e, 0, 1);
        String second = table.addSymbol(e, 0, 1);
        Assert.assertSame("repeated calls for same colliding string must return same reference", first, second);
    }

}

