package com.alibaba.json.bvt.util;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import com.alibaba.fastjson.util.ThreadLocalCache;
import org.junit.Assert;

import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.serializer.SerializeWriter;
import com.alibaba.fastjson.util.IOUtils;

import junit.framework.TestCase;

public class ThreadLocalCacheTest extends TestCase {

    public void testGetAllocateLengthExpOverflow() throws Exception {
        // Directly test the private getAllocateLengthExp method via reflection
        Method method = ThreadLocalCache.class.getDeclaredMethod(
            "getAllocateLengthExp", int.class, int.class, int.class);
        method.setAccessible(true);

        // Test 1: length = 0 should return 1 << minExp = 1024 (not 1)
        int resultZero = (Integer) method.invoke(null, 10, 17, 0);
        Assert.assertEquals(1024, resultZero);

        // Test 2: Normal values work correctly
        int r;
        r = (Integer) method.invoke(null, 10, 17, 1024);
        Assert.assertEquals("length=1024", 1024, r);
        r = (Integer) method.invoke(null, 10, 17, 1025);
        Assert.assertEquals("length=1025", 2048, r);
        r = (Integer) method.invoke(null, 10, 17, 2048);
        Assert.assertEquals("length=2048", 2048, r);
        r = (Integer) method.invoke(null, 10, 17, 2049);
        Assert.assertEquals("length=2049", 4096, r);
        r = (Integer) method.invoke(null, 10, 17, 131072);
        Assert.assertEquals("length=131072", 131072, r);

        // Test 3: For large inputs (> 2^30), the method returns a NEGATIVE value
        // due to shift overflow: 1 << 31 = Integer.MIN_VALUE
        // length = 2^30 + 1: length-1 = 2^30, nlz(2^30)=1, shift=31, 1<<31 = MIN_VALUE
        int resultLarge = (Integer) method.invoke(null, 10, 31, 1073741825);
        Assert.assertTrue("getAllocateLengthExp should return positive value for large inputs but got: " + resultLarge,
            resultLarge > 0);

        // Test 4: Negative length values that bypass the part <= 0 check
        // can produce nonsensical results (shift = 32 wraps to 0, result = 1)
        // length = -1: length >>> 10 > 0 (unsigned shift makes it large positive),
        // so we reach line 73; length-1 = -2, nlz(-2) = 0, shift = 32, 1 << 32 = 1
        int resultNeg = (Integer) method.invoke(null, 10, 31, -1);
        Assert.assertTrue("getAllocateLengthExp should not return 1 for negative input but got: " + resultNeg,
            resultNeg > 1);
    }

    public void test() throws Exception {

        clearChars();
        Assert.assertEquals(allocateChars(0).length, 1024 * 64);
        Assert.assertEquals(allocateChars(1024).length, 1024 * 64);
        Assert.assertEquals(allocateChars(2048).length, 1024 * 64);
        Assert.assertEquals(allocateChars(0).length, 1024 * 64);
        Assert.assertEquals(allocateChars(1024 * 128).length, 1024 * 128);
        Assert.assertEquals(allocateChars(0).length, 1024 * 64);

        clearChars();
        Assert.assertEquals(allocateChars(2048).length, 1024 * 64);

        clearChars();
        Assert.assertEquals(allocateChars(1024 * 256).length, 1024 * 256);
        Assert.assertEquals(allocateChars(0).length, 1024 * 64);
        clearChars();

    }

    static char[] allocateChars(int length) throws Exception {
        Method method = JSON.class.getDeclaredMethod("allocateChars", int.class);
        method.setAccessible(true);
        return (char[]) method.invoke(null, length);
    }

    public static void clearChars() throws Exception {
        Field field = JSON.class.getDeclaredField("charsLocal");
        field.setAccessible(true);

        ThreadLocal<char[]> charsLocal = (ThreadLocal<char[]>) field.get(null);
        charsLocal.set(null);
    }

    public void testBytes() throws Exception {

        clearBytes();
        Assert.assertEquals(getBytes(0).length, 8192);
        Assert.assertEquals(getBytes(1024).length, 8192);
        Assert.assertEquals(getBytes(8192 * 2).length, 8192 * 2);
        Assert.assertEquals(getBytes(0).length, 8192);
        Assert.assertSame(getBytes(0), getBytes(1204));
        Assert.assertNotSame(getBytes(9000), getBytes(9000));

        clearBytes();
        Assert.assertEquals(getBytes(2048).length, 8192);

        clearBytes();
        Assert.assertEquals(getBytes(1024 * 256).length, 1024 * 256);
        Assert.assertEquals(getBytes(0).length, 8192);
        clearBytes();

    }

    public static byte[] getBytes(int length) throws Exception {
        Field field = SerializeWriter.class.getDeclaredField("bytesBufLocal");
        field.setAccessible(true);
        ThreadLocal<byte[]> bytesBufLocal = (ThreadLocal<byte[]>) field.get(null);

        byte[] bytes = bytesBufLocal.get();

        if (bytes == null) {
            bytes = new byte[1024 * 8];
            bytesBufLocal.set(bytes);
        }

        return bytes.length < length //
            ? new byte[length] //
            : bytes;
    }

    public static void clearBytes() throws Exception {
        Field field = SerializeWriter.class.getDeclaredField("bytesBufLocal");
        field.setAccessible(true);
        ThreadLocal<byte[]> bytesBufLocal = (ThreadLocal<byte[]>) field.get(null);
        bytesBufLocal.set(null);
    }

    public void test_chars() throws Exception {
        ThreadLocalCache.getChars(10);
        ThreadLocalCache.getChars(10);
        ThreadLocalCache.getChars(20);
        ThreadLocalCache.getChars(30);
        clearChars();
        ThreadLocalCache.getChars(10);
        ThreadLocalCache.getChars(10);
        ThreadLocalCache.getChars(20);
        ThreadLocalCache.getChars(30);

        ThreadLocalCache.clearChars();
        ThreadLocalCache.getUTF8Decoder();
        ThreadLocalCache.getUTF8Decoder();
    }

    public void test_bytes() throws Exception {
        ThreadLocalCache.getBytes(10);
        ThreadLocalCache.getBytes(10);
        ThreadLocalCache.getBytes(20);
        ThreadLocalCache.getBytes(30);
        clearBytes();
        ThreadLocalCache.getBytes(10);
        ThreadLocalCache.getBytes(10);
        ThreadLocalCache.getBytes(20);
        ThreadLocalCache.getBytes(30);

    }

}

